'use client'

import axiosInstance from '@/api/axiosInstance';
import { useEffect, useState } from 'react';

export default function Resource() {
    const [data, setData] = useState([]); // Original data
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [query, setQuery] = useState(""); // Search query state

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await axiosInstance.get("/api/resources");
                setData(response.data);
            } catch (error) {
                setError(error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    // Filter resources on the frontend
    const filteredData = data.filter((item) =>
        item.title.toLowerCase().includes(query.toLowerCase()) ||
        item.description.toLowerCase().includes(query.toLowerCase()) ||
        item.body?.toLowerCase().includes(query.toLowerCase()) // Optional check
    );

    return (
        <div className="container mx-auto px-4">
            <h1 className="text-3xl font-bold text-gray-800 mb-6 text-center">Latest Resources</h1>

            {/* Search Bar */}
            <div className="relative mb-6">
            <input
                type="text"
                placeholder="Search resources..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <svg
                className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400"
                xmlns="http://www.w3.org/2000/svg"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
            >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-4.35-4.35M15 11a4 4 0 100-8 4 4 0 000 8z" />
            </svg>
        </div>

            {/* Loading State */}
            {loading && <p className="text-center text-gray-500">Loading...</p>}
            {error && <p className="text-center text-red-500">Error loading resources.</p>}

            {/* Resources Grid */}
            <div className="grid gap-6 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
                {filteredData.length > 0 ? (
                    filteredData.map((item) => (
                        <div key={item._id} className="bg-white shadow-lg rounded-xl p-6 hover:shadow-xl transition duration-300">
                            <h2 className="text-xl font-semibold text-gray-800 mb-2">{item.title}</h2>
                            <p className="text-gray-600 mb-3">{item.description}</p>
                            <p className="text-gray-700 text-sm">{item.body}</p>
                            <p className="text-sm text-gray-500 mt-4">
                                Posted by: <span className="font-medium text-gray-700">{item.username}</span>
                            </p>
                        </div>
                    ))
                ) : (
                    <p className="text-center text-gray-500 col-span-3">No matching resources found.</p>
                )}
            </div>
        </div>
    );
}
